def check_M2(x1):
    # Required sum condition (3) implies x2 = 16*x1^2 / (15*x1 - 16)
    numerator_x2 = 16 * x1**2
    denominator_x2 = 15 * x1 - 16

    if denominator_x2 <= 0:
        return None, "Invalid x1"

    x2_sum = numerator_x2 / denominator_x2

    # Minimal constraint (2) requires x2 >= 1 + x1^3 - x1^2
    x2_min = 1 + x1**3 - x1**2

    return x2_sum, x2_min

test_values = range(2, 15)
results = {}
for x1 in test_values:
    x2_sum, x2_min_req = check_M2(x1)
    if x2_sum is not None:
        results[x1] = {'x2_sum': x2_sum, 'x2_min_req': x2_min_req}

print(results)

